    food_fy19 = next((v for v in value_list if v['category'] == 'Foodservice' and v['header1'] == 'Fiscal 2019 Net Sales'), None)

    if intl_fy18 and intl_fy19 and food_fy18 and food_fy19:
        intl_change = (intl_fy19['number_value'] - intl_fy18['number_value']) / intl_fy18['number_value'] * 100
