    outstanding_2019 = value_list[1]['number_value']
    difference = outstanding_2019 - outstanding_2018
    if difference > 0:
        scale = 'Thousand' if abs(difference) < 1000000 else 'Million' if abs(difference) < 1000000000 else 'Billion'
        scale = 'Percent' if difference / outstanding_2018 < 0.01 else ''
    else:
        scale = 'Thousand' if abs(difference) < 1000000 else 'Million' if abs(difference) < 1000000000 else 'Billion'
