def run(value_list):
    total_gross_margin = 0
    total_revenue = 0
    total_count = 0

    for item in value_list:
        if item['category'] == 'Professional Service Gross Margin' or item['category'] == 'Other Gross Margin':
            total_gross_margin += item['value']
            total_count += 1
        if item['category'] == 'Revenue':
            total_revenue += item['value']

    if total_count == 0:
        return (0, '')

    average_gross_margin = total_gross_margin / total_count
    average_gross_margin = round(average_gross_margin, 2)

    if average_gross_margin >= 1000000:
        scale = 'million'
    elif average_gross_margin >= 1000:
        scale = 'thousand'
    elif average_gross_margin >= 1:
        scale = ''
    else:
        scale = ''

    return (average_gross_margin, scale)

